    """Create a DeepEval model adapter from a model URI.

    Native backends (databricks, MLflow deployments, supported providers with
    the required API keys, and gateway endpoints) return a
    :class:`MlflowDeepEvalLLM`. Unsupported providers fall back to litellm.
    """
    client = ScorerLLMClient(model_uri)

    if client.is_native:
        return MlflowDeepEvalLLM(client)

    from deepeval.models import LiteLLMModel

    return LiteLLMModel(
        model=client.model_name,
        generation_kwargs={"drop_params": True},
    )
